// ---------------------------------------------------------------------------
// Attribute rule system
// ---------------------------------------------------------------------------

type AttrSpec =
  | { kind: 'string' }
  | { kind: 'number' }
  | { kind: 'length' }
  | { kind: 'range' }
  | { kind: 'ident' }
  | { kind: 'enum'; values: readonly string[] };

interface AttrRules {
  attrs: Record<string, AttrSpec>;
  flags: string[];
}

